CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- =========================================================
-- USUARIOS
-- =========================================================

CREATE TABLE IF NOT EXISTS usuarios
(
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(100) NOT NULL,
    "Apellido" VARCHAR(100) NOT NULL,
    "UsuarioRed" VARCHAR(50) NOT NULL UNIQUE,
    "Correo" VARCHAR(150) NOT NULL UNIQUE,
    "Proceso" VARCHAR(100) NOT NULL,
    "Activo" BOOLEAN NOT NULL DEFAULT TRUE,
    "PasswordHash" VARCHAR(255),
    "UltimoAcceso" TIMESTAMPTZ,
    "FechaCreacion" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "IX_usuarios_UsuarioRed"
    ON usuarios("UsuarioRed");

CREATE INDEX IF NOT EXISTS "IX_usuarios_Correo"
    ON usuarios("Correo");


-- =========================================================
-- EQUIPMENT
-- =========================================================

CREATE TABLE IF NOT EXISTS equipment
(
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    inventory_key VARCHAR(100) NOT NULL UNIQUE,

    empresa VARCHAR(150),
    asignado_a VARCHAR(200),
    acta_entregada BOOLEAN,
    proveedor VARCHAR(150),

    nombre_equipo VARCHAR(150) NOT NULL,
    hoja_de_vida TEXT,

    marca VARCHAR(100),
    procesador VARCHAR(200),
    disco_duro VARCHAR(150),
    memoria_ram VARCHAR(100),

    descripcion TEXT,
    departamento VARCHAR(150),
    estatus_equipo VARCHAR(100),

    mantenimiento_realizado BOOLEAN,
    tipo_mantenimiento VARCHAR(150),
    fecha_mantenimiento DATE,

    observaciones TEXT,

    source_system VARCHAR(50) NOT NULL DEFAULT 'P8-FR-019',
    last_sync_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS ix_equipment_nombre
    ON equipment(nombre_equipo);

CREATE INDEX IF NOT EXISTS ix_equipment_estado
    ON equipment(estatus_equipo);